void example() {
    // Stack allocation - automatic, fast, limited size
    int stack_array[100];
    int x = 42;

    // Heap allocation - manual, larger, slower
    int* heap_array = malloc(100 * sizeof(int));
    *heap_array = 42;

    // Must free heap memory!
    free(heap_array);
}  // stack_array and x automatically freed here

struct Example {
    char a;      // 1 byte + 3 bytes padding
    int b;       // 4 bytes (aligned to 4)
    char c;      // 1 byte + 3 bytes padding
};               // Total: 12 bytes (not 6!)

// Optimized order:
struct Optimized {
    int b;       // 4 bytes
    char a;      // 1 byte
    char c;      // 1 byte
    // + 2 bytes padding to align to 4
};               // Total: 8 bytes
